-- Owner-finalized shared celebration reviews. No guest data or finances enter snapshots.
begin;
create table if not exists public.cb_experience_reviews(event_id uuid primary key references public.cb_project_events on delete cascade,data jsonb not null,status text not null check(status in ('Draft','Finalized')),source_hash text not null,metrics jsonb not null,revision bigint not null default 1,updated_at timestamptz not null default now(),finalized_at timestamptz,finalized_by uuid references auth.users);
create table if not exists public.cb_experience_review_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_experience_review_history(event_id uuid not null references public.cb_project_events on delete cascade,revision bigint not null,actor_id uuid not null references auth.users,action text not null,reason text not null default '',snapshot jsonb not null,at timestamptz not null default now(),primary key(event_id,revision));
alter table public.cb_experience_reviews enable row level security;alter table public.cb_experience_review_writes enable row level security;alter table public.cb_experience_review_history enable row level security;
revoke all on public.cb_experience_reviews,public.cb_experience_review_writes,public.cb_experience_review_history from public,anon,authenticated;
create or replace function public.cb_experience_review_source(p_event uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.cb_project_events;result jsonb;begin
 select * into e from public.cb_project_events where id=p_event;if e.id is null or not coalesce(public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration access required' using errcode='42501';end if;
 select jsonb_build_object('hash',md5(jsonb_build_object('event_revision',e.revision,'items',(select coalesce(string_agg(id::text||':'||revision::text,',' order by id),'') from public.cb_experience_items where event_id=e.id),'cues',(select coalesce(string_agg(item_id::text||':'||revision::text,',' order by item_id),'') from public.cb_experience_cues where event_id=e.id),'issues',(select coalesce(string_agg(id::text||':'||revision::text,',' order by id),'') from public.cb_experience_issues where event_id=e.id))::text),'metrics',jsonb_build_object('services',(select count(*) from public.cb_experience_items where event_id=e.id and data->>'status'<>'Cancelled'),'services_ready',(select count(*) from public.cb_experience_items where event_id=e.id and data->>'status' in ('Ready','Complete')),'cues',(select count(*) from public.cb_experience_cues where event_id=e.id and not removed),'cues_complete',(select count(*) from public.cb_experience_cues where event_id=e.id and not removed and status='Complete'),'cues_skipped',(select count(*) from public.cb_experience_cues where event_id=e.id and not removed and status='Skipped'),'cues_running',(select count(*) from public.cb_experience_cues where event_id=e.id and not removed and status='Running'),'issues_open',(select count(*) from public.cb_experience_issues where event_id=e.id and data->>'status'<>'Resolved'),'issues_resolved',(select count(*) from public.cb_experience_issues where event_id=e.id and data->>'status'='Resolved'),'issues_blocking',(select count(*) from public.cb_experience_issues where event_id=e.id and blocks and data->>'status'<>'Resolved'))) into result;return result;
end;$$;
create or replace function public.cb_experience_review(p_event uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.cb_project_events;r public.cb_experience_reviews;src jsonb;begin
 src=public.cb_experience_review_source(p_event);select * into e from public.cb_project_events where id=p_event;select * into r from public.cb_experience_reviews where event_id=p_event;
 return jsonb_build_object('event',e.id,'title',e.title,'can_edit',public.cb_project_access(e.project_id,'write'),'owner',public.cb_project_access(e.project_id,'owner'),'source',src,'review',case when r.event_id is null then null else jsonb_build_object('data',r.data,'status',r.status,'metrics',r.metrics,'revision',r.revision,'updated_at',r.updated_at,'finalized_at',r.finalized_at,'source_changed',r.source_hash<>src->>'hash') end,'history',(select coalesce(jsonb_agg(jsonb_build_object('revision',h.revision,'status',h.snapshot->>'status','action',h.action,'at',h.at) order by h.revision desc),'[]') from (select * from public.cb_experience_review_history where event_id=e.id order by revision desc limit 30) h));end;$$;
create or replace function public.cb_save_experience_review(p_event uuid,p_revision bigint,p_source_hash text,p_client uuid,p_action text,p_data jsonb,p_reason text,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.cb_project_events;r public.cb_experience_reviews;src jsonb;w public.cb_experience_review_writes;payload jsonb;result jsonb;k text;begin
 select * into e from public.cb_project_events where id=p_event;perform 1 from public.cb_projects where id=e.project_id for update;
 if e.id is null or not coalesce(public.cb_project_access(e.project_id,'write') and public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration planning access required' using errcode='42501';end if;
 payload=jsonb_build_object('event',p_event,'revision',p_revision,'source_hash',p_source_hash,'action',p_action,'data',p_data,'reason',p_reason,'confirm',p_confirm);
 if p_client is null then raise exception 'Request ID required';end if;select * into w from public.cb_experience_review_writes where user_id=auth.uid() and client=p_client;if found then if w.payload is distinct from payload then raise exception 'Retry the original celebration review' using errcode='PT409';end if;return w.response;end if;
 if p_confirm is distinct from true or p_action is null or p_action not in ('SaveDraft','Finalize','Reopen') or p_reason is null or length(p_reason)>1000 then raise exception 'Review and confirm a valid review action';end if;
 if p_action in ('Finalize','Reopen') and not public.cb_project_access(e.project_id,'owner') then raise exception 'Only the wedding owner can finalize or reopen the review' using errcode='42501';end if;
 src=public.cb_experience_review_source(p_event);if src->>'hash' is distinct from p_source_hash then raise exception 'Celebration records changed. Refresh the review totals before saving.' using errcode='PT409';end if;
 select * into r from public.cb_experience_reviews where event_id=p_event for update;if coalesce(r.revision,0) is distinct from p_revision then raise exception 'Another teammate updated this review. Refresh first.' using errcode='PT409';end if;
 if p_action='Reopen' then
 if r.event_id is null or r.status<>'Finalized' or p_data is not null or length(btrim(p_reason))=0 then raise exception 'Choose a finalized review and explain why it is being reopened';end if;
 update public.cb_experience_reviews set status='Draft',finalized_at=null,finalized_by=null,revision=revision+1,updated_at=now() where event_id=e.id returning * into r;
 else
 if r.status='Finalized' then raise exception 'Reopen the finalized review before changing it';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or p_data-array['summary','highlights','lessons','nextSteps']::text[]<>'{}' then raise exception 'Review the celebration notes';end if;
 foreach k in array array['summary','highlights','lessons','nextSteps'] loop if jsonb_typeof(p_data->k) is distinct from 'string' or length(p_data->>k)>3000 then raise exception 'Keep each review field within 3000 characters';end if;end loop;
 if length(btrim(p_data->>'summary'))=0 then raise exception 'Add a celebration summary';end if;
 if p_action='Finalize' and ((src->'metrics'->>'cues_running')::bigint>0 or (src->'metrics'->>'issues_blocking')::bigint>0) then raise exception 'Finish running cues and resolve or clear blocking issues before finalizing';end if;
 insert into public.cb_experience_reviews(event_id,data,status,source_hash,metrics,finalized_at,finalized_by) values(e.id,p_data,case when p_action='Finalize' then 'Finalized' else 'Draft' end,src->>'hash',src->'metrics',case when p_action='Finalize' then now() end,case when p_action='Finalize' then auth.uid() end) on conflict(event_id) do update set data=excluded.data,status=excluded.status,source_hash=excluded.source_hash,metrics=excluded.metrics,finalized_at=excluded.finalized_at,finalized_by=excluded.finalized_by,revision=public.cb_experience_reviews.revision+1,updated_at=now() returning * into r;
 end if;
 insert into public.cb_experience_review_history values(e.id,r.revision,auth.uid(),p_action,p_reason,to_jsonb(r),now());result=jsonb_build_object('saved',true,'revision',r.revision,'status',r.status);insert into public.cb_experience_review_writes values(auth.uid(),p_client,payload,result);return result;
end;$$;
revoke all on function public.cb_experience_review_source(uuid),public.cb_experience_review(uuid),public.cb_save_experience_review(uuid,bigint,text,uuid,text,jsonb,text,boolean) from public,anon,authenticated;
grant execute on function public.cb_experience_review(uuid),public.cb_save_experience_review(uuid,bigint,text,uuid,text,jsonb,text,boolean) to authenticated;
notify pgrst,'reload schema';commit;
